def chart():
    rows=''.join(f'<div class="bar-row"><div class="bar-label"><span>{name}</span><strong>{n}/50 defects</strong></div><div class="bar-track"><div class="bar-fill {"best" if n==43 else ""}" style="width:{n*2}%"></div></div></div>' for name,n in [('Full image · 256 px',36),('Board crop · 256 px',41),('Board crop · 512 px',43)])
    return f'<div class="chart"><p class="eyebrow">PCB2 · development comparison</p><h3>What changes when you look closer?</h3><div class="bars">{rows}</div><div class="chart-note"><span>False alarms: 3/50 → 2/50 → 1/50</span><span>Median: 22.8 → 25.2 → 38.5 ms</span></div><p style="margin:18px 0 0">50 anomalous + 50 normal images. Each model normal-calibrated. Local laptop CUDA timings; independent evaluation pending.</p></div>'

